<div class="row" style="justify-content:space-between;margin-top:24px"><div><p class="muted" style="margin:0">ORDER OVERVIEW</p><h1 style="margin-top:4px">Dashboard</h1></div><label style="margin:0;min-width:180px">Order date<input id="order-date" type="date" value="{{ $date }}"></label></div>
<div class="grid admin-stats"><div class="panel"><span class="muted">Orders</span><h2 id="stat-orders">{{ $stats['totalOrders'] }}</h2></div><div class="panel"><span class="muted">Sales</span><h2 id="stat-sales">Rs. {{ number_format($stats['totalSales'],2) }}</h2></div><div class="panel"><span class="muted">New orders</span><h2 id="stat-new">{{ $stats['newOrders'] }}</h2></div><div class="panel"><span class="muted">Completed</span><h2 id="stat-completed">{{ $stats['completedOrders'] }}</h2></div></div>
<script>const endpoint=@json(route('admin.dashboard.data')),dateInput=document.querySelector('#order-date'),money=value=>`Rs. ${Number(value||0).toFixed(2)}`;async function loadStats(){try{const response=await fetch(`${endpoint}?date=${encodeURIComponent(dateInput.value)}`,{headers:{Accept:'application/json'}});if(!response.ok)return;const data=await response.json();document.querySelector('#stat-orders').textContent=data.stats.totalOrders;document.querySelector('#stat-sales').textContent=money(data.stats.totalSales);document.querySelector('#stat-new').textContent=data.stats.newOrders;document.querySelector('#stat-completed').textContent=data.stats.completedOrders}catch(error){}}dateInput.addEventListener('change',loadStats);setInterval(()=>{if(!document.hidden)loadStats()},2000);</script>
@endsection
